 header('Content-Type: application/json; charset=utf-8');if((int)($_SERVER['CONTENT_LENGTH']??0)>2048||($_SERVER['HTTP_ORIGIN']??'')!=='http://'.$host||!hash_equals($csrf,$_SERVER['HTTP_X_CSRF_TOKEN']??'')){http_response_code(403);exit('{"error":"Forbidden"}');}
